mapper.select:
SELECT p.pin_id, p.image_url, p.title, (SELECT board_id FROM saved_pin sp WHERE sp.pin_id = p.pin_id AND ROWNUM = 1) AS board_id, p.created_at FROM pin p WHERE 1=1
AND pin_id < #{cursorId}
ORDER BY pin_id DESC FETCH FIRST #{size} ROWS ONLY

SELECT image_url
FROM pin
WHERE pin_id = #{pinId}

SELECT p.pin_id, p.image_url, p.title, p.created_at, LISTAGG(t.tag_name, ',') WITHIN GROUP (ORDER BY t.tag_name) AS tags FROM pin p LEFT JOIN pin_tag pt ON p.pin_id = pt.pin_id LEFT JOIN tag t ON pt.tag_id = t.tag_id WHERE ( LOWER(p.title) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(t.tag_name) LIKE '%' || LOWER(#{keyword}) || '%' )
AND p.pin_id < #{cursorId}
GROUP BY p.pin_id, p.image_url, p.title, p.created_at ORDER BY p.pin_id DESC FETCH FIRST #{size} ROWS ONLY

